dslRule:
/*!
@id: math.abs-min-value-fix
@description: Apply Math.abs() twice for modulo operations on potentially negative values to prevent negative array indices, fixing Integer.MIN_VALUE edge cases. Replaces Math.abs(expr) % divisor with Math.abs(Math.abs(expr) % divisor).
@severity: ERROR
*/
java.lang.Math.abs($expr) % $divisor
=>
java.lang.Math.abs(java.lang.Math.abs($expr) % $divisor)
;;

beforeExample:
public class MyClass {
    private static final int SEGMENT_QUOTA = 10;
    private static final char[][] HEX_STRINGS = new char[10][]; // Dummy array

    private char[] translateSegment(String segment) {
        // String.hashCode() can produce Integer.MIN_VALUE.
        // Math.abs(Integer.MIN_VALUE) is still Integer.MIN_VALUE.
        // Integer.MIN_VALUE % SEGMENT_QUOTA can be negative, leading to ArrayIndexOutOfBoundsException.
        return HEX_STRINGS[Math.abs(segment.hashCode()) % SEGMENT_QUOTA];
    }

    public void testMethod() {
        int val = Integer.MIN_VALUE;
        int result = Math.abs(val) % 10; // result is -8
        System.out.println(result);

        int a = 10;
        int b = 3;
        int c = Math.abs(a * b - 50) % 7; // Matches the pattern
        System.out.println(c);
    }
}

afterExample:
public class MyClass {
    private static final int SEGMENT_QUOTA = 10;
    private static final char[][] HEX_STRINGS = new char[10][]; // Dummy array

    private char[] translateSegment(String segment) {
        // The nested Math.abs ensures the final index is always non-negative.
        return HEX_STRINGS[java.lang.Math.abs(java.lang.Math.abs(segment.hashCode()) % SEGMENT_QUOTA)];
    }

    public void testMethod() {
        int val = Integer.MIN_VALUE;
        int result = java.lang.Math.abs(java.lang.Math.abs(val) % 10); // result is 8
        System.out.println(result);

        int a = 10;
        int b = 3;
        int c = java.lang.Math.abs(java.lang.Math.abs(a * b - 50) % 7); // Replacement applied
        System.out.println(c);
    }
}

negativeExample:
public class MyClass {
    private static final int SEGMENT_QUOTA = 10;
    private static final char[][] HEX_STRINGS = new char[10][];

    // Does not match: no modulo operation
    private int getAbsHashCode(String segment) {
        return Math.abs(segment.hashCode());
    }

    // Does not match: no initial Math.abs
    private int getModuloHashCode(String segment) {
        return segment.hashCode() % SEGMENT_QUOTA;
    }

    // Does not match: different structure (addition instead of modulo)
    private int calculate(int x, int y) {
        return Math.abs(x) + y;
    }
}
